window.futvizVista("local-visitante","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"local-visitante\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"local-visitante\"]={\"id\":\"local-visitante\",\"titulo\":\"Local vs. visitante\",\"bajada\":\"A la derecha, mejor diferencia de xG de local; arriba, de visitante. Las l\u00edneas est\u00e1n en cero.\",\"pregunta\":\"\u00bfQui\u00e9n depende de su estadio?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_dif_local\",\"label\":\"Diferencia de xG por partido, de local\",\"corto\":\"De local\",\"dec\":2},\"y\":{\"col\":\"xg_dif_visita\",\"label\":\"Diferencia de xG por partido, de visitante\",\"corto\":\"De visitante\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"Dominan de local y de visita\",\"tl\":\"Dominan solo de visita\",\"br\":\"Dominan solo de local\",\"bl\":\"Sufren de local y de visita\"},\"fijo\":{\"x\":0,\"y\":0},\"etiqueta\":\"L\u00edneas punteadas en cero\"},\"requiere\":[\"xg_dif_local\",\"xg_dif_visita\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 diferencia de xG por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"De local\",\"ayuda\":\"Ordenados por Diferencia de xG por partido, de local\"},{\"id\":\"y\",\"etiqueta\":\"De visitante\",\"ayuda\":\"Ordenados por Diferencia de xG por partido, de visitante\"}],\"queMirar\":\"Compara c\u00f3mo le va a cada equipo de local y de visitante, medido por la diferencia de xG por partido: el xG que crea menos el que concede, sin penales. El eje horizontal es esa diferencia jugando en casa y el vertical, jugando fuera. Las l\u00edneas est\u00e1n en cero: a la derecha y arriba, el equipo crea m\u00e1s de lo que concede en esa sede. Cada punto es un equipo de la temporada elegida.\",\"insight\":\"local_visitante\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");